    grey_mode = value.get("grey_mode", False)
    if not isinstance(grey_mode, bool):
        raise MonitoringCaseError("Moduskennzeichnung des Ausgangsbeweises ist ungültig.")
    cleaned["grey_mode"] = grey_mode
