    if not isinstance(documents, list) or not documents:
        raise MonitoringCaseError("Ausgangsbeweis enthält keinen normalisierten Seitentext.")
    cleaned_documents: list[dict[str, str]] = []
    total_size = 0
    seen_roles: set[str] = set()
