            raise MonitoringCaseError("Seitentexte des Ausgangsbeweises sind unvollständig.")
        if not SHA256_PATTERN.fullmatch(digest):
            raise MonitoringCaseError("Seitentext-Prüfwert des Ausgangsbeweises ist ungültig.")

