} from "../src/lib/minimal-tenor-logic.ts";
import { composeDictationText, mergeDictationSegments } from "../src/lib/dictation.ts";
import { splitAlternativeLabels, splitLineValues } from "../src/lib/monitoring-form.ts";
import {
