    "Text aus 8 von 11 Seiten berücksichtigt · gekürzt",
  );
  assert.equal(
    formatPdfExtractionStatus({ ...extraction, extracted_pages: 11, truncated: false }),
    "Text aus 11 Seiten berücksichtigt",
  );
});

