  1: import { createFileRoute } from "@tanstack/react-router";
  2: import { useQueryClient } from "@tanstack/react-query";
  3: import {
  4:   AlertTriangle,
  5:   CheckCircle2,
  6:   ChevronDown,
  7:   ChevronRight,
  8:   Clock,
  9:   HelpCircle,
 10:   Scale,
 11:   X,
 12: } from "lucide-react";
 13: import { useCallback, useEffect, useRef, useState } from "react";
 14: import { toast } from "sonner";
 15: 
 16: import { useCaseViews } from "../data/caseViews";
 17: import type { Tone } from "../data/lottoDemoCases";
 18: import {
 19:   getMonitoringRun,
 20:   monitoringCasesQueryKey,
 21:   reviewMonitoringCase,
 22:   startMonitoringRun,
 23:   type EngineAssessment,
 24: } from "../lib/monitoring-api";
 25: import {
 26:   claimMonitoringChangeNotification,
 27:   EVIDENCE_COMPARISON_NOTIFICATION_KEY,
 28:   EVIDENCE_COMPARISON_NOTIFICATION_QUERY,
 29:   parseStoredEvidenceComparisonNotification,
 30:   type MonitoringChangeNotification,
 31: } from "../lib/monitoring-notifications";
 32: 
 33: export const Route = createFileRoute("/hinweise")({
 34:   head: () => ({
 35:     meta: [
 36:       { title: "Hinweise – Muc Legal Monitoring" },
 37:       {
 38:         name: "description",
 39:         content:
 40:           "Aktuelle Hinweise aus dem Monitoring als Benachrichtigungen – mit Zeitstempel, Kontext und vollständiger Beweisführung.",
 41:       },
 42:       { property: "og:title", content: "Hinweise – Muc Legal Monitoring" },
 43:       {
 44:         property: "og:description",
 45:         content:
 46:           "Aktuelle Hinweise aus dem Monitoring als Benachrichtigungen – mit Zeitstempel, Kontext und vollständiger Beweisführung.",
 47:       },
 48:       { property: "og:type", content: "website" },
 49:       { name: "twitter:card", content: "summary" },
 50:     ],
 51:   }),
 52:   component: HinweisePage,
 53: });
 54: 
 55: const toneIcon: Record<Tone, typeof Scale> = {
 56:   danger: AlertTriangle,
 57:   success: CheckCircle2,
 58:   warning: HelpCircle,
 59:   neutral: Clock,
 60: };
 61: 
 62: const toneColor: Record<Tone, string> = {
 63:   danger: "text-danger bg-danger/10",
 64:   success: "text-success bg-success/10",
 65:   warning: "text-warning bg-warning/10",
 66:   neutral: "text-muted-foreground bg-muted",
 67: };
 68: 
 69: const toneLabel: Record<Tone, string> = {
 70:   danger: "Kritisch",
 71:   success: "In Ordnung",
 72:   warning: "Prüfung nötig",
 73:   neutral: "Ausstehend",
 74: };
 75: 
 76: const enginePresentation: Record<
 77:   EngineAssessment["classification"],
 78:   {
 79:     label: string;
 80:     summary: string;
 81:     icon: typeof Scale;
 82:     className: string;
 83:     iconClassName: string;
 84:   }
 85: > = {
 86:   kerngleich: {
 87:     label: "Kerngleich",
 88:     summary: "Die Engine stuft den geprüften Stand als kerngleich ein.",
 89:     icon: AlertTriangle,
 90:     className: "border-danger/40 bg-danger/5",
 91:     iconClassName: "bg-danger/10 text-danger",
 92:   },
 93:   nicht_kerngleich: {
 94:     label: "Nicht kerngleich",
 95:     summary: "Die Engine stuft den geprüften Stand als nicht kerngleich ein.",
 96:     icon: CheckCircle2,
 97:     className: "border-success/40 bg-success/5",
 98:     iconClassName: "bg-success/10 text-success",
 99:   },
100:   unklar: {
101:     label: "Nicht eindeutig",
102:     summary: "Die Engine konnte die Kerngleichheit nicht abschließend bestimmen.",
103:     icon: HelpCircle,
104:     className: "border-warning/50 bg-warning/5",
105:     iconClassName: "bg-warning/10 text-warning",
106:   },
107:   noch_nicht_bewertet: {
108:     label: "Noch nicht bewertet",
109:     summary: "Für den aktuellen Stand liegt noch kein Engine-Befund vor.",
110:     icon: Clock,
111:     className: "border-border bg-muted/50",
112:     iconClassName: "bg-background text-muted-foreground",
113:   },
114: };
115: 
116: const notificationToneClass: Record<MonitoringChangeNotification["tone"], string> = {
117:   danger: "border-danger/40 text-danger",
118:   success: "border-success/40 text-success",
119:   warning: "border-warning/50 text-warning",
120: };
121: 
122: const MONITORING_POLL_INTERVAL_MS = 500;
123: // The backend domain scan may legitimately use its full ten-minute budget.
124: // Keep the UI attached for one additional minute so artifact creation can finish.
125: const MONITORING_POLL_ATTEMPTS = (11 * 60 * 1_000) / MONITORING_POLL_INTERVAL_MS;
126: 
127: function relativeTime(iso: string | null) {
128:   if (!iso) return "geplant";
129:   const now = Date.now();
130:   const mins = Math.max(1, Math.round((now - new Date(iso).getTime()) / 60000));
131:   if (mins < 60) return `vor ${mins} Min.`;
132:   const hours = Math.round(mins / 60);
133:   if (hours < 24) return `vor ${hours} Std.`;
134:   return `vor ${Math.round(hours / 24)} Tg.`;
135: }
136: 
137: function formatDateTime(iso: string | null) {
138:   if (!iso) return "—";
139:   return new Date(iso).toLocaleString("de-DE", {
140:     day: "2-digit",
141:     month: "2-digit",
142:     year: "numeric",
143:     hour: "2-digit",
144:     minute: "2-digit",
145:     timeZone: "Europe/Berlin",
146:   });
147: }
148: 
149: function HinweisePage() {
150:   const { cases } = useCaseViews();
151:   const queryClient = useQueryClient();
152:   const [openId, setOpenId] = useState<string | null>(null);
153:   const [actionState, setActionState] = useState<Record<string, string>>({});
154:   const notifiedRunIds = useRef(new Set<string>());
155:   const pendingEvidenceId = useRef<string | null>(null);
156: 
157:   const openEvidence = useCallback((caseId: string) => {
158:     pendingEvidenceId.current = caseId;
159:     setOpenId(caseId);
160:   }, []);
161: 
162:   useEffect(() => {
163:     const caseId = pendingEvidenceId.current;
164:     if (!caseId || openId !== caseId) return;
165:     const target =
166:       document.getElementById(`engine-assessment-${caseId}`) ??
167:       document.getElementById(`differenz-${caseId}`) ??
168:       document.getElementById(`beweisfuehrung-${caseId}`);
169:     if (!target) return;
170:     pendingEvidenceId.current = null;
171:     window.requestAnimationFrame(() => {
172:       target.scrollIntoView({ behavior: "smooth", block: "center" });
173:       target.focus({ preventScroll: true });
174:     });
175:   }, [cases, openId]);
176: 
177:   const showChangeNotification = useCallback(
178:     (runId: string, caseId: string, fallId: string, notification: MonitoringChangeNotification) => {
179:       toast.custom(
180:         (toastId) => {
181:           const Icon = notification.tone === "success" ? CheckCircle2 : AlertTriangle;
182:           return (
183:             <div
184:               className={`flex w-[min(92vw,34rem)] overflow-hidden rounded-2xl border bg-card text-card-foreground shadow-xl ${notificationToneClass[notification.tone]}`}
185:               role="status"
186:             >
187:               <button
188:                 type="button"
189:                 onClick={() => {
190:                   toast.dismiss(toastId);
191:                   openEvidence(caseId);
192:                 }}
193:                 className="group flex min-w-0 flex-1 items-start gap-3 p-4 text-left transition-colors hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
194:                 aria-label={`${notification.title} in Fall ${fallId}. Hinweis öffnen.`}
195:               >
196:                 <span className="mt-0.5 grid size-9 shrink-0 place-items-center rounded-full bg-current/10">
197:                   <Icon className="size-5" strokeWidth={1.75} />
198:                 </span>
199:                 <span className="min-w-0 flex-1">
200:                   <span className="block text-xs font-medium text-muted-foreground">
201:                     Fall {fallId}
202:                   </span>
203:                   <span className="mt-0.5 block font-semibold text-card-foreground">
204:                     {notification.title}
205:                   </span>
206:                   <span className="mt-1 block text-sm text-muted-foreground">
207:                     {notification.description}
208:                   </span>
209:                 </span>
210:                 <ChevronRight
211:                   className="mt-2 size-5 shrink-0 text-muted-foreground transition-transform group-hover:translate-x-0.5"
212:                   strokeWidth={1.75}
213:                 />
214:               </button>
215:               <button
216:                 type="button"
217:                 onClick={() => toast.dismiss(toastId)}
218:                 className="grid w-11 shrink-0 place-items-center border-l border-border text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
219:                 aria-label="Benachrichtigung schließen"
220:               >
221:                 <X className="size-4" strokeWidth={1.75} />
222:               </button>
223:             </div>
224:           );
225:         },
226:         { duration: Infinity, id: `monitoring-change-${runId}` },
227:       );
228:     },
229:     [openEvidence],
230:   );
231: 
232:   useEffect(() => {
233:     const currentUrl = new URL(window.location.href);
234:     const queryHandoff = currentUrl.searchParams.get(EVIDENCE_COMPARISON_NOTIFICATION_QUERY);
235:     const raw = window.sessionStorage.getItem(EVIDENCE_COMPARISON_NOTIFICATION_KEY) ?? queryHandoff;
236:     const stored = parseStoredEvidenceComparisonNotification(raw);
237:     if (raw) window.sessionStorage.removeItem(EVIDENCE_COMPARISON_NOTIFICATION_KEY);
238:     if (queryHandoff) {
239:       currentUrl.searchParams.delete(EVIDENCE_COMPARISON_NOTIFICATION_QUERY);
240:       window.history.replaceState(window.history.state, "", currentUrl);
241:     }
242:     if (!stored) return;
243:     openEvidence(stored.case_id);
244:   }, [openEvidence]);
245: 
246:   async function decide(caseId: string, decision: "freigegeben" | "abgelehnt") {
247:     setActionState((state) => ({ ...state, [caseId]: "Entscheidung wird gespeichert …" }));
248:     try {
249:       await reviewMonitoringCase(caseId, decision);
250:       await queryClient.invalidateQueries({ queryKey: monitoringCasesQueryKey });
